import requests

BASE_URL = "http://localhost:3000"
SIGNIN_PATH = "/api/auth/signin"
TIMEOUT = 30


def test_post_api_auth_signin_authenticate_user_and_get_jwt():
    url = f"{BASE_URL}{SIGNIN_PATH}"
    headers = {"Content-Type": "application/json"}

    # Valid credentials test
    valid_payload = {
        "email": "test_pawal@yopmail.com",
        "password": "Wlink123"
    }
    try:
        response = requests.post(url, json=valid_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Valid signin request failed: {e}"
    assert response.status_code == 200, f"Expected 200, got {response.status_code}"
    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert "token" in data and isinstance(data["token"], str) and data["token"], "Missing or invalid token"
    assert "user" in data and isinstance(data["user"], dict), "Missing or invalid user object"
    user = data["user"]
    required_user_fields = {"id", "name", "email", "role"}
    for field in required_user_fields:
        assert field in user, f"User object missing field: {field}"
    assert user["email"] == valid_payload["email"], f"User email mismatch: expected {valid_payload['email']}, got {user['email']}"
    assert user["role"] == "AGENCY_OWNER", f"User role expected 'AGENCY_OWNER', got {user['role']}"

    # Wrong password test (should return 401)
    wrong_password_payload = {
        "email": "test_pawal@yopmail.com",
        "password": "WrongPassword123"
    }
    try:
        response = requests.post(url, json=wrong_password_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Signin request with wrong password failed: {e}"
    assert response.status_code == 401, f"Expected 401 for wrong password, got {response.status_code}"

    # Nonexistent email test (should return 401)
    nonexistent_email_payload = {
        "email": "nonexistent_email_abc123@yopmail.com",
        "password": "Wlink123"
    }
    try:
        response = requests.post(url, json=nonexistent_email_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Signin request with nonexistent email failed: {e}"
    assert response.status_code == 401, f"Expected 401 for nonexistent email, got {response.status_code}"

    # Missing fields tests (should return 400)
    # Missing email
    missing_email_payload = {
        "password": "Wlink123"
    }
    try:
        response = requests.post(url, json=missing_email_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Signin request missing email failed: {e}"
    assert response.status_code == 400, f"Expected 400 for missing email, got {response.status_code}"

    # Missing password
    missing_password_payload = {
        "email": "test_pawal@yopmail.com"
    }
    try:
        response = requests.post(url, json=missing_password_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Signin request missing password failed: {e}"
    assert response.status_code == 400, f"Expected 400 for missing password, got {response.status_code}"

    # Missing both email and password (empty body)
    empty_payload = {}
    try:
        response = requests.post(url, json=empty_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Signin request empty body failed: {e}"
    assert response.status_code == 400, f"Expected 400 for missing email and password, got {response.status_code}"


test_post_api_auth_signin_authenticate_user_and_get_jwt()

import requests

BASE_URL = "http://localhost:3000"
EMAIL = "test_pawal@yopmail.com"
PASSWORD = "Wlink123"
TIMEOUT = 30

def test_get_api_auth_me_return_current_user_profile_with_role():
    signin_url = f"{BASE_URL}/api/auth/signin"
    me_url = f"{BASE_URL}/api/auth/me"

    # Step 1: Sign in to obtain valid JWT token
    signin_payload = {"email": EMAIL, "password": PASSWORD}
    try:
        signin_resp = requests.post(signin_url, json=signin_payload, timeout=TIMEOUT)
        assert signin_resp.status_code == 200, f"Signin failed with status {signin_resp.status_code}"
        signin_data = signin_resp.json()
        token = signin_data.get("token")
        assert token and isinstance(token, str), "Token missing or invalid in signin response"
    except Exception as e:
        raise AssertionError(f"Sign in request failed: {e}")

    headers_valid = {"Authorization": f"Bearer {token}"}

    # Test 1: Valid Authorization header returns 200 with correct user info and role=AGENCY_OWNER
    try:
        resp = requests.get(me_url, headers=headers_valid, timeout=TIMEOUT)
    except Exception as e:
        raise AssertionError(f"GET /api/auth/me request with valid token failed: {e}")

    assert resp.status_code == 200, f"Expected 200 for valid token, got {resp.status_code}"
    try:
        json_resp = resp.json()
    except Exception as e:
        raise AssertionError(f"GET /api/auth/me response invalid JSON: {e}")

    # The user object may be nested inside 'user' key or directly returned
    if isinstance(json_resp, dict) and 'user' in json_resp:
        user_obj = json_resp.get('user')
    else:
        user_obj = json_resp

    # Validate user fields existence and types
    for field in ["id", "name", "email", "role"]:
        assert field in user_obj, f"Field '{field}' missing from user profile"
        assert isinstance(user_obj[field], str), f"Field '{field}' is not string type"
    # Validate role is AGENCY_OWNER
    assert user_obj["role"] == "AGENCY_OWNER", f"User role expected 'AGENCY_OWNER', got '{user_obj['role']}'"

    # Test 2: Missing Authorization header returns 401
    try:
        resp = requests.get(me_url, timeout=TIMEOUT)
    except Exception as e:
        raise AssertionError(f"GET /api/auth/me request without auth header failed: {e}")
    assert resp.status_code == 401, f"Expected 401 for missing Authorization header, got {resp.status_code}"

    # Test 3: Invalid/garbage token returns 401
    invalid_headers = {"Authorization": "Bearer garbage.invalid.token"}
    try:
        resp = requests.get(me_url, headers=invalid_headers, timeout=TIMEOUT)
    except Exception as e:
        raise AssertionError(f"GET /api/auth/me request with invalid token failed: {e}")
    assert resp.status_code == 401, f"Expected 401 for invalid token, got {resp.status_code}"

    # Test 4: Expired token returns 401
    expired_token = (
        "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9."
        "eyJ1c2VySWQiOiJiZGY0YWJhNi1iMGFlLTQ4MTUtYWQ0Mi02Mzk1NWM2NTQzMDciLCJlbWFpbCI6InRlc3RfcGF3YWxAeW9wbWFpbC5jb20iLCJyb2xlIjoiQUdFTkNZX09XTkVSIiwiaWF0IjoxNzc0Njg4MjU1LCJleHAiOjE3NzUyOTMwNTV9."
        "LFtQEgaHNMtNyMuaVMA6aEj92lbRUs6UPJy0y4I3BI0"
    )
    expired_headers = {"Authorization": f"Bearer {expired_token}"}
    try:
        resp = requests.get(me_url, headers=expired_headers, timeout=TIMEOUT)
    except Exception as e:
        raise AssertionError(f"GET /api/auth/me request with expired token failed: {e}")
    assert resp.status_code == 401, f"Expected 401 for expired token, got {resp.status_code}"

